{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "DialogHeader",
    "subComponentOf": "Dialog",
    "displayName": "Dialog Header",
    "isHiddenFromOverview": true,
    "description": "Header for dialogs with a title, optional subtitle, close button, and start/end content slots.",
    "usage": {
      "description": "Use DialogHeader to give a dialog a labelled title area and optional close control.",
      "anatomy": [
        {
          "name": "Header row",
          "required": true,
          "description": "Arranges the title block, optional start/end content, and close control."
        },
        {
          "name": "Start content",
          "required": false,
          "description": "Wraps optional leading content."
        },
        {
          "name": "Title block",
          "required": true,
          "description": "Groups the title and optional subtitle."
        },
        {
          "name": "End content",
          "required": false,
          "description": "Groups optional trailing content with the optional close control."
        },
        {
          "name": "Close icon",
          "required": false,
          "description": "Visual close glyph inside the close button."
        }
      ]
    },
    "props": [
      {
        "name": "title",
        "type": "ReactNode",
        "description": "Dialog title, rendered inside the focusable h2 (receives focus on open; its text content labels the dialog via aria-labelledby unless the Dialog has an explicit aria-label/aria-labelledby). Keep it inline, non-interactive, and non-empty."
      },
      {
        "name": "subtitle",
        "type": "ReactNode",
        "description": "Subtitle below the title. Accepts inline content such as a Link; avoid block elements."
      },
      {
        "name": "onOpenChange",
        "type": "(isOpen: boolean) => unknown",
        "description": "Close button callback (no button if omitted)."
      },
      {
        "name": "startContent",
        "type": "ReactNode",
        "description": "Content before the title (e.g., a back button).",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "check",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content after the title, before close button.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "chevronDown",
              "size": "sm"
            }
          },
          {
            "__element": "Badge",
            "props": {
              "label": "3"
            }
          }
        ]
      },
      {
        "name": "endContentEdgeCompensation",
        "type": "'inline' | 'block' | 'all'",
        "description": "Selects compensation axes for the end-content slot. Omit to preserve automatic close-action compensation."
      },
      {
        "name": "hasDivider",
        "type": "boolean",
        "description": "Adds border at the bottom edge.",
        "default": "true"
      }
    ],
    "playground": {
      "defaults": {
        "title": "Delete file?",
        "subtitle": "This action cannot be undone.",
        "hasDivider": true
      }
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-dialog-header"
        },
        {
          "className": "astryx-dialog-header-start-content"
        },
        {
          "className": "astryx-dialog-header-title-block"
        },
        {
          "className": "astryx-dialog-header-end-content"
        },
        {
          "className": "astryx-dialog-header-close-icon"
        }
      ]
    },
    "examples": [
      {
        "label": "Basic",
        "code": "\nimport {DialogHeader} from '@astryxdesign/core/Dialog';\n\n<DialogHeader title=\"Delete file?\" subtitle=\"This action cannot be undone.\" />;\n"
      },
      {
        "label": "With close button",
        "code": "\nimport {useState} from 'react';\nimport {DialogHeader} from '@astryxdesign/core/Dialog';\n\nfunction Header() {\n  const [, setIsOpen] = useState(true);\n\n  // Passing onOpenChange renders a close button that calls it with false.\n  return <DialogHeader title=\"Settings\" onOpenChange={setIsOpen} />;\n}\n"
      },
      {
        "label": "With a link in the subtitle",
        "code": "\nimport {DialogHeader} from '@astryxdesign/core/Dialog';\nimport {Link} from '@astryxdesign/core/Link';\n\n<DialogHeader\n  title=\"Share conversation\"\n  subtitle={\n    <>\n      Anyone with the link can view it. Review the{' '}\n      <Link href=\"#sharing-policy\">sharing policy</Link> first.\n    </>\n  }\n/>;\n"
      },
      {
        "label": "With start and end content",
        "code": "\nimport {DialogHeader} from '@astryxdesign/core/Dialog';\nimport {Icon} from '@astryxdesign/core/Icon';\nimport {Badge} from '@astryxdesign/core/Badge';\n\n<DialogHeader\n  title=\"Notifications\"\n  startContent={<Icon icon=\"chevronLeft\" size=\"sm\" />}\n  endContent={<Badge label=\"3\" />}\n/>;\n"
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Dialog",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
